// Pure checks of the Phase-6 view models (assets/hq-carnet-ask.js) on the REAL JSON the server returns
// (tests/fixtures_carnet_ask.json, generated by tests/gen_fixtures_carnet_ask.py from the Python implementation).
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const A = require("../assets/hq-carnet-ask.js");
const FX = JSON.parse(readFileSync(new URL("./fixtures_carnet_ask.json", import.meta.url), "utf8"));
let groups = 0;
const group = (name, fn) => {
  try {
    fn();
    groups += 1;
  } catch (e) {
    console.error("FAIL group:", name);
    throw e;
  }
};
const clone = (x) => JSON.parse(JSON.stringify(x));
const P = "page-" + "a".repeat(8);
const PR = "proj-" + "b".repeat(8);
const SN = "snap-" + "c".repeat(24);

group("question validation", () => {
  assert.equal(A.validQuestion("  couple   de serrage ").text, "couple de serrage");
  assert.equal(A.validQuestion("   ").ok, false);
  assert.equal(A.validQuestion(null).ok, false);
  assert.equal(A.validQuestion("x".repeat(301)).ok, false);
  assert.equal(A.validQuestion("x".repeat(300)).ok, true);
  assert.equal(A.validQuestion("a\u0000b").ok, false);
});

group("scope choices: current project is the default, widening is explicit, snapshots only when sealed", () => {
  const ch = A.scopeChoices({ page: { id: P }, projects: [{ id: PR, name: "Banc" }, { id: "proj-" + "d".repeat(8), name: "Autre" }], projectId: PR, snapshots: [{ id: SN, label: "Gel", integrity: "ok" }, { id: "snap-" + "e".repeat(24), label: "Cassé", integrity: "corrupt" }] });
  assert.deepEqual(ch.map((c) => c.value), ["page", "project", "project:proj-dddddddd", "snapshot:" + SN, "notebook"]);
  assert.equal(A.defaultScope(ch), "project");
  assert.deepEqual(ch[1].scope, { kind: "project", id: PR });
  assert.deepEqual(ch[4].scope, { kind: "notebook" });
  assert.equal(A.defaultScope(A.scopeChoices({ projects: [], projectId: "none" })), "project");
  assert.equal(A.scopeChoices({ page: { id: "bad" } }).some((c) => c.value === "page"), false);
});

group("request body is exactly the wire shape", () => {
  assert.deepEqual(A.requestBody(" serrage ", { kind: "notebook", extra: 1 }), { action: "ask", question: "serrage", scope: { kind: "notebook" } });
  assert.deepEqual(A.requestBody("a", { kind: "page", id: P }, 5), { action: "ask", question: "a", scope: { kind: "page", id: P }, limit: 5 });
  assert.equal(A.requestBody("a", { kind: "page", id: P }, 99).limit, undefined);
  assert.equal(A.requestBody("", { kind: "notebook" }), null);
  assert.equal(A.requestBody("a", null), null);
});

group("highlight clamps, sorts and merges spans", () => {
  assert.deepEqual(A.highlight("abcdef", [[4, 6], [0, 2], [1, 3]]).map((s) => [s.text, s.hit]), [["abc", true], ["d", false], ["ef", true]]);
  assert.deepEqual(A.highlight("abc", [[-5, 99]]).map((s) => s.text), ["abc"]);
  assert.deepEqual(A.highlight("abc", [[2, 2], ["x", 1], null]).map((s) => s.hit), [false]);
  assert.deepEqual(A.highlight(null, null), []);
  for (const c of FX.evidence.cards) assert.equal(A.highlight(c.excerpt, c.marks).map((s) => s.text).join(""), c.excerpt);
});

group("status wording per server status — never colour alone, never a generated answer", () => {
  const e = A.statusModel(FX.evidence);
  assert.equal(e.tone, "evidence");
  assert.ok(e.mark && e.title.includes("1 passage") && !e.title.includes("tous les termes"));
  assert.ok(e.notes.some((n) => n.includes("ne prouve une absence")));
  // r2: the server's threshold is ceil(60%) for >2 terms, so the title must never claim "all terms"
  const sixty = clone(FX.evidence);
  sixty.terms = ["palier", "avant", "couple", "serrage", "inox"];
  sixty.cards[0].matched = ["palier", "avant", "couple"];
  sixty.cards[0].coverage = 0.6;
  const st60 = A.statusModel(sixty);
  assert.ok(!/tous les termes/.test(st60.title + st60.text), "no 'all terms' claim: " + st60.title);
  assert.ok(st60.title.includes("pertinent"), st60.title);
  assert.equal(A.cardModel(sixty.cards[0], sixty).coverage, 60);
  const p = A.statusModel(FX.partial);
  assert.equal(p.tone, "partial");
  assert.ok(p.text.includes("grenaillé") || p.text.includes("grenaille"), p.text);
  const i = A.statusModel(FX.insufficient);
  assert.equal(i.tone, "insufficient");
  assert.ok(i.title.includes("Pas assez de preuves"));
  assert.equal(A.statusModel(FX.empty).tone, "empty");
  assert.equal(A.statusModel(null).tone, "error");
  const inc = clone(FX.evidence);
  inc.incomplete = true;
  assert.ok(A.statusModel(inc).notes.some((n) => n.includes("tout n'a pas été parcouru")));
});

group("cards: derived text keeps its source relation and says so when the source is missing", () => {
  const m = A.resultModel(FX.evidence);
  assert.equal(m.cards.length, 1);
  const prim = A.cardModel(FX.evidence.cards[0], FX.evidence);
  assert.equal(prim.derived, false);
  assert.equal(prim.provenance, null);
  assert.ok(prim.link.startsWith("#carnet/page-"));
  const part = A.resultModel(FX.partial);
  const d = part.cards.find((c) => c.derived);
  assert.ok(d, "an OCR-derived card exists");
  assert.equal(d.provenance.kind, "ocr");
  assert.equal(d.provenance.state, "ok");
  assert.ok(d.provenance.sourceLink && d.provenance.sourceFound);
  assert.ok(d.provenance.text.includes("n'est pas la source"));
  const miss = clone(FX.partial.cards.find((c) => c.class === "derived"));
  miss.provenance.source.block = null;
  miss.provenance.source.state = "missing";
  const mm = A.cardModel(miss, FX.partial);
  assert.equal(mm.provenance.sourceLink, null);
  assert.equal(mm.provenance.sourceFound, false);
  assert.equal(mm.provenance.stateLabel, "Introuvable");
  assert.ok(mm.provenance.text.includes("n'est pas dans ce périmètre"));
});

group("deep links are validated, never trusted", () => {
  const c = clone(FX.evidence.cards[0]);
  c.link = "javascript:alert(1)";
  assert.equal(A.cardModel(c, FX.evidence).link, null);
  c.link = "#carnet/page-x/block-y/../../z";
  assert.equal(A.cardModel(c, FX.evidence).link, null);
});

group("frozen: states are those sealed at freeze; the current state is added only when it differs", () => {
  const c = clone(FX.frozen.cards.find((x) => x.provenance));
  assert.equal(c.provenance.source.current_state, "ok");
  assert.equal(A.cardModel(c, FX.frozen).provenance.currentLabel, "");
  c.provenance.source.current_state = "missing";
  assert.equal(A.cardModel(c, FX.frozen).provenance.currentLabel, "Maintenant : introuvable");
  assert.equal(A.cardModel(c, FX.frozen).provenance.stateLabel, "Disponible");
});

group("frozen snapshot: no live link unless exactly unchanged; state always stated", () => {
  const r = A.resultModel(FX.frozen);
  assert.ok(r.frozen && r.frozen.label === "Gel conception");
  for (const c of r.cards) {
    assert.equal(c.link, null);
    assert.ok(c.liveLabel.length > 0);
    if (c.liveState !== "unchanged") assert.equal(c.liveLink, null);
  }
  assert.ok(r.cards.some((c) => c.liveState === "changed"), "the edited paragraph is reported as changed");
  assert.ok(r.cards.some((c) => c.liveState === "unchanged" && c.liveLink));
});

group("measure / decision / drawing extras", () => {
  const m = A.cardModel({ id: "x", kind: "measure", class: "primary", page_id: P, block_id: "block-1", link: null, excerpt: "Ø 10", marks: [], matched: [], coverage: 1, at: 1790000000, measure: { label: "Ø", value: "10.02", unit: "mm", verdict: "out" }, refs: [] }, {});
  assert.equal(m.measure.value, "10.02 mm");
  assert.equal(m.measure.verdictLabel, "Hors tolérance");
  assert.match(m.date, /^\d{4}-\d{2}-\d{2} \d{2}:\d{2} UTC$/);
  const d = A.cardModel({ id: "y", kind: "drawing", class: "primary", page_id: P, drawing: { stem: "plan-1", state: "missing" }, matched: [], refs: [] }, {});
  assert.equal(d.drawing.stateLabel, "Introuvable");
});

group("report item: only evidence/partial, fingerprint pinned, scope echoed, nothing else", () => {
  const item = A.reportItem(FX.evidence, { kind: "project", id: PR });
  assert.deepEqual(Object.keys(item).sort(), ["fingerprint", "kind", "label", "question", "scope"]);
  assert.equal(item.kind, "ask_evidence");
  assert.equal(item.fingerprint, FX.evidence.fingerprint);
  assert.equal(A.reportItem(FX.insufficient, { kind: "notebook" }), null);
  assert.equal(A.reportItem(FX.empty, { kind: "notebook" }), null);
  const bad = clone(FX.evidence);
  bad.fingerprint = "zz";
  assert.equal(A.reportItem(bad, { kind: "notebook" }), null);
  assert.equal(A.resultModel(FX.insufficient).canReport, false);
  assert.equal(A.resultModel(FX.evidence).canReport, true);
});

group("the module has no DOM, network, storage, clock or dynamic code", () => {
  const src = readFileSync(new URL("../assets/hq-carnet-ask.js", import.meta.url), "utf8").replace(/\/\*[\s\S]*?\*\//g, "").split("\n").filter((l) => !/^\s*\/\//.test(l)).join("\n");
  for (const banned of ["document.", "window.", "fetch(", "XMLHttpRequest", "localStorage", "sessionStorage", "indexedDB", "Date.now", "new Date()", "eval(", "new Function", "innerHTML", "setTimeout", "navigator."]) assert.ok(!src.includes(banned), banned);
  const ui = readFileSync(new URL("../assets/hq-carnet-ask-ui.js", import.meta.url), "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
  for (const banned of ["innerHTML", "outerHTML", "insertAdjacentHTML", "eval(", "new Function", "localStorage", "sessionStorage", "indexedDB", "document.write", "Date.now"]) assert.ok(!ui.includes(banned), "ui: " + banned);
});

console.log("check_hq_carnet_ask: " + groups + " groups OK");
